import { useEffect, useRef, useState } from 'react';
import Avatar from '../components/Avatar.jsx';
import Icon from '../components/Icon.jsx';
import PlanPanel from '../components/PlanPanel.jsx';
import useUserMedia from '../hooks/useUserMedia.js';
import useMicLevel from '../hooks/useMicLevel.js';
import ProviderChips from '../components/ProviderChips.jsx';
import { createVoiceAgent, VOICE_WANTS_AUDIO, IS_LIVE_VOICE, VOICE_PATH, DEBUG } from '../agents/index.js';
import { isSpeechMuted, setSpeechMuted, resolveVoiceName, onVoicesChanged } from '../agents/speech.js';
import { loadCapabilities, voiceCallProviders } from '../agents/providers.js';
import { VOICE_AGENT_URL } from '../config.js';
import { validateTriage } from '../contracts.js';
import { gradiumSupports, gradiumVoiceName, resolveVoiceChoice } from '../agents/gradiumVoice.js';
import VoicePicker from '../components/VoicePicker.jsx';

// Pawse's voice in a live call: a Gradium voice id (default) or 'gemini' (Gemini Live native audio). Remembered per browser.
const VOICE_KEY = 'pawse.liveVoice';
function loadVoiceChoice() {
  try {
    return localStorage.getItem(VOICE_KEY) || '';
  } catch {
    return '';
  }
}

function fmt(sec) {
  return `${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`;
}

// Voice first. The camera and photos are optional extras the user can add any time.
export default function VoiceCall({ t, lang, triage, vet, insurance, onTriage, rail, onCall, onEnd }) {
  const [consent, setConsent] = useState(false);
  const [voiceChoice, setVoiceChoiceState] = useState(loadVoiceChoice);
  const setVoiceChoice = (v) => {
    setVoiceChoiceState(v);
    try {
      localStorage.setItem(VOICE_KEY, v);
    } catch {
      /* storage unavailable */
    }
  };
  // A Gradium voice only applies in a language Gradium speaks; otherwise the call uses Gemini's voice.
  const gradiumVoice = resolveVoiceChoice(voiceChoice, lang);
  const [toolResults, setToolResults] = useState([]);
  const [trace, setTrace] = useState([]);
  const [camOn, setCamOn] = useState(false);
  const [facing, setFacing] = useState('environment');
  const [micOn, setMicOn] = useState(!IS_LIVE_VOICE);
  const [soundOn, setSoundOn] = useState(!isSpeechMuted());
  const [aiLine, setAiLine] = useState('');
  const [userLine, setUserLine] = useState('');
  const [userPartial, setUserPartial] = useState(false);
  const [transcribing, setTranscribing] = useState(false);
  const [speaking, setSpeaking] = useState('none');
  const [listening, setListening] = useState(false);
  const [chips, setChips] = useState([]);
  const [draft, setDraft] = useState('');
  const [photos, setPhotos] = useState([]); // { url, received }
  const [error, setError] = useState('');
  const [sheetOpen, setSheetOpen] = useState(true);
  const [secs, setSecs] = useState(0);
  const [caps, setCaps] = useState(null);
  const [browser, setBrowser] = useState(() => resolveVoiceName(lang));

  const videoRef = useRef(null);
  const fileRef = useRef(null);
  const agentRef = useRef(null);
  const photoUrls = useRef([]);
  const onTriageRef = useRef(onTriage);
  onTriageRef.current = onTriage;

  const mic = useUserMedia({ enabled: VOICE_WANTS_AUDIO && consent && micOn, audio: true });
  const cam = useUserMedia({ enabled: camOn, video: true, facing });
  // Recording = the mic is open and the agent is taking it in. The meter shows the owner it hears them.
  const recording = VOICE_WANTS_AUDIO && micOn && !!mic.stream && listening;
  const level = useMicLevel(recording ? mic.stream : null);
  const hearing = recording && level >= 0.15;

  // ---- the conversation with Pawse
  useEffect(() => {
// A location the browser grants goes with the clinic search; without one the server uses central Zurich.
const located=createGeminiLiveAgent({...options,locate:async()=>({lat:47.5,lng:8.7})});await located.start();
