 async resume(){} async close(){this.closed=true;}
 createMediaStreamSource(media){attached.push(media.id);return {connect(){},disconnect(){}};}
};
globalThis.AudioWorkletNode=class {constructor(){this.port={};}connect(){}disconnect(){}};
